import type { ScheduleDefinition } from '@n8n/constants';
import type { ScheduledJob } from '../types';
export type { ScheduleDefinition, CronDefinition, RecurringCronDefinition, IntervalDefinition, OneOffDefinition, } from '@n8n/constants';
export interface DesiredJob {
    name: string;
    schedule: ScheduleDefinition;
    firstRunAt: Date | null;
}
export interface ExistingJob {
    id: number;
    name: string;
    schedule: ScheduleDefinition;
    hasClock: boolean;
}
export interface ProvisionedJob {
    id: number;
    name: string;
}
export interface ProvisionSummary {
    inserted: ProvisionedJob[];
    redefined: ProvisionedJob[];
    unchanged: ProvisionedJob[];
    removed: ProvisionedJob[];
}
export interface StoredJobs {
    now: Date;
    jobs: Array<ScheduledJob & {
        enabled: boolean;
    }>;
}
